"""Fuzzy-match heap regions between two dumps by 64-byte content shingles."""
import json, sys, hashlib
from pathlib import Path

ROOT = Path(r"<G5A_WORKDIR>")

def load(tag):
    d = (ROOT / f'_work/t1/{tag}').read_bytes()
    idx = json.loads((ROOT / f'_work/t1/{tag}.idx.json').read_text())
    return d, idx

def shingles(b, step=16, k=64):
    return {hashlib.blake2b(b[i:i+k], digest_size=8).digest() for i in range(0, max(0, len(b)-k), step)}

d1, i1 = load(sys.argv[1])
d2, i2 = load(sys.argv[2])
tag1, tag2 = sys.argv[1], sys.argv[2]

# only heap-like regions: low addresses (non-DLL), exclude stacks/PEB (small ones ok to include)
def heapy(r):
    a = r['addr']
    return a < 0x7ff000000000 and r['size'] >= 65536

regs2 = []
for r in i2:
    if heapy(r):
        b = d2[r['off']:r['off']+r['size']]
        regs2.append((r['addr'], r['size'], shingles(b)))
print(f'dump2 heap regions: {len(regs2)}, total shingles {sum(len(s) for _,_,s in regs2)}')

for r in i1:
    if not heapy(r):
        continue
    b1 = d1[r['off']:r['off']+r['size']]
    s1 = shingles(b1)
    hits = []
    for addr, size, s2 in regs2:
        inter = len(s1 & s2)
        if inter > 10:
            hits.append((inter, addr, size))
    if hits:
        hits.sort(reverse=True)
        print(f'{tag1} addr={r["addr"]:#x} size={r["size"]}: matches {[(i2, hex(a), s) for i2, a, s in hits[:3]]}')
